public void writeShort(int v) throws IOException{
    if (byteOrder == ByteOrder.BIG_ENDIAN) {
        byteBuf[0] = (byte) (v >>> 8);
        byteBuf[1] = (byte) (v >>> 0);
    } else {
        byteBuf[0] = (byte) (v >>> 0);
        byteBuf[1] = (byte) (v >>> 8);
    }
    write(byteBuf, 0, 2);
}

