    assertEquals("Pixel suspect of adjacency effects", adjacencyFlag.getDescription());
    assertEquals(4, adjacencyFlag.getData().getElemInt());
    final ProductNodeGroup<Mask> maskGroup = targetProduct.getMaskGroup();
