/**
 * Returns this Calendar's time value in milliseconds.
 *
 * @return the current time as UTC milliseconds from the epoch.
 * @see #getTime()
 * @see #setTimeInMillis(long)
 */
public long getTimeInMillis(){
    if (!isTimeSet) {
        updateTime();
    }
    return time;
