public Calendar getAsCalendar(){
    Calendar calendar = createCalendar();
    calendar.add(5, this.getDaysFraction());
    calendar.add(13, (int) this.getSecondsFraction());
    calendar.add(14, (int) Math.round((double) this.getMicroSecondsFraction() / (double) 1000.0F));
    return calendar;
}

public UTC(double mjd){
    super(3);
    double microSeconds = mjd * (double) 86400.0F * (double) 1000000.0F % (double) 1000000.0F;
    double seconds = mjd * (double) 86400.0F % (double) 86400.0F;
    double days = (double) ((int) mjd);
    if (microSeconds < (double) 0.0F) {
        microSeconds += (double) 1000000.0F;
        --seconds;
    }
    this.setElemIntAt(0, (int) days);
    this.setElemIntAt(1, (int) seconds);
    this.setElemIntAt(2, (int) microSeconds);
}

public static UTC parse(String text) throws ParseException{
    return parse(text, "dd-MMM-yyyy HH:mm:ss");
}

