    assertArrayEquals(rwExpected, result1.rwa, 1e-4);
    double[] iopsExpected1 = new double[] { 0.012507978418952223, 0.0021061919389812633, 9.761536702823946E-5, 0.31943759388761156, 0.028129863341225206 };
    assertArrayEquals(iopsExpected1, result1.iops_nn, 1e-2);
